			item = await controller.forkHandler(sessionResource, requestTurn, token);
		} else if (entry.sessionObj.session.forkHandler) {
			item = await entry.sessionObj.session.forkHandler(sessionResource, requestTurn, token);
		} else {
			throw new Error(`Chat session does not support forking: ${sessionResource}`);
		}

		return typeConvert.ChatSessionItem.from(item);
	}

